export default function BJGTAnalysisPage() {
  const { unlocked, unlock } = usePasswordGate();

  if (!unlocked) return <PasswordGate onUnlock={unlock} />;

  return <BJGTContent />;
}

/** Nome no contest → nome na lista D (a ficha do jogador procura pelo nome exacto). */
function nomeNaListaD(p: ContestPlayer): string {
  if (p.isM) return D.find(d => d.isM)?.n ?? p.n;
  const k = norm(p.n);
  return D.find(d => norm(d.n) === k)?.n ?? p.n;
}

function BJGTContent() {
  // 10/11/2026: a página carregava a ficha de um federado (o do URL) e ficava
  // presa em «a carregar» / «sem campo Villa Padierna» por uma análise que já não
  // é mostrada — o que se vê são as classificações fixas dos 4 contests e a ficha
  // de cada jogador. A análise (e as médias do field, também sem uso) saiu.
  const [tab, setTab] = useState<ContestKey>("26_1011");
  const md = useMasterDetail();
  const [selectedPlayer, setSelectedPlayer] = useState<string | null>(null);

  return (
    <div className="tourn-layout">

      {/* ── Toolbar ── */}
      <Toolbar>
        <SidebarToggle open={md.open} onToggle={md.toggle} backLabel="Lista" />
        <ToolbarTitle>🇪🇸 BJGT</ToolbarTitle>
        <ToolbarMeta>📍 {TOURN.location}</ToolbarMeta>
        <ToolbarMeta>📅 {TOURN.dates}</ToolbarMeta>
        <ToolbarMeta>🏷️ {PLAYER_NAME} · Sub-12</ToolbarMeta>
        <ToolbarSep />
        <TabRow
          tabs={CONTEST_KEYS.map(k => ({ key: k, label: CONTEST_LABELS[k] }))}
          active={tab}
          onChange={(k) => { setTab(k); setSelectedPlayer(null); }}
        />
        <Counter ml="auto">{fmtFieldInfo(CONTEST_MAP[tab].players.filter(p=>typeof p.p==="number").length, CONTEST_MAP[tab].nRounds, `Par ${CONTEST_MAP[tab].par}`)}</Counter>
      </Toolbar>

      {/* ── Master-detail ── */}
      <MasterDetail md={md} sidebar={<>
          <div className="sidebar-section-title">
            {CONTEST_LABELS[tab]}
          </div>
          {/* 10/11/2026: as linhas eram <div> sem clique — a ficha do jogador
              (FieldPlayerDetail) existia mas nada a abria. */}
          {CONTEST_MAP[tab].players.filter(p => p.rd.length > 0).map((p, idx) => {
            const nome = nomeNaListaD(p);
            return (
              <button type="button" key={idx} title={`Abrir a ficha de ${p.n}`}
                onClick={() => { setSelectedPlayer(nome); md.onSelect(); }}
                className={"course-item u-p-6px-12px u-d-flex u-jc-space-between u-ai-center u-bb-1px-solid-border-light"
                  + (selectedPlayer === nome ? " active" : "") + (p.isM ? " u-bg-bg-success-subtle" : "")}>
                <span className="course-item-name">
                  <span className={"fs-11 fw-800 u-minw-22px " + (typeof p.p === "number" && p.p <= 3 ? "u-c-color-warn-dark" : "u-c-text-3")}>{typeof p.p === "number" ? `${p.p}.` : ""}</span>
                  {flag(p.co)} {firstName(p.n)}
                </span>
                <span className="course-item-meta u-fvn-tabular-nums">
                  {p.t} ({fmtToPar(p.tp)})
                </span>
              </button>
            );
          })}
      </>}>

      {/* ═══ PLAYER DETAIL (from sidebar click) ═══ */}
      {selectedPlayer && (
        <FieldPlayerDetail playerName={selectedPlayer} onBack={() => setSelectedPlayer(null)} T={T} D={D} />
      )}

      {/* ═══ CONTEST LEADERBOARD (all 4 tabs) ═══ */}
      {!selectedPlayer && (
        <ContestLeaderboard
          contest={CONTEST_MAP[tab]}
          evo={tab === "26_1011" ? EVOLUTION.filter(e => e.to === "10-11") : tab === "26_1213" ? EVOLUTION.filter(e => e.to === "12-13") : undefined}
        />
      )}

      </MasterDetail>
    </div>
  );
}
